/* ---------- Avisos y ventanas ---------- */
let tAviso;
function aviso(t) { const a = $('aviso'); a.textContent = t; a.classList.remove('oculto'); clearTimeout(tAviso); tAviso = setTimeout(() => a.classList.add('oculto'), 2600); }
function ventana(html, botones) {
  $('ventana').innerHTML = html + `<div class="botones">${botones.map((b, k) => `<button class="${b.clase || 'si'}" data-k="${k}">${b.t}</button>`).join('')}</div>`;
  $('velo').classList.remove('oculto');
  $('ventana').scrollTop = 0;
  $('ventana').querySelectorAll('.botones button').forEach(e => e.onclick = () => { $('velo').classList.add('oculto'); botones[+e.dataset.k].f && botones[+e.dataset.k].f(); });
}


