const NIVELES = ['Fácil', 'Normal', 'Difícil', 'Experta', 'Gemini (IA)', 'DeepSeek (IA)'], ICONIV = ['🟢', '🟡', '🔴', '🧠', '✨', '🐋'];
const COLORES_LETRA = ['#e07a3a', '#2f8a5b', '#3b6fd1', '#b03a7a'];
function opcionesAvatar() {
  const ini = ((PREF.nombre || '?').trim()[0] || '?').toUpperCase();
  return (PREF.fotoGoogle ? ['google'] : []).concat(NOMBRES_P, COLORES_LETRA.map(c => `letra:${ini}:${c}`));
}
function rivalesSentados() {
  const yo = (PREF.nombre || '').trim().toLowerCase();
  return (PREF.rivales || []).filter(n => PERSONAJES[n] && n.toLowerCase() !== yo);
}
function rivalesElegidos() {
  // los que eligió, sin ella misma, completando con el resto si faltan
  const yo = (PREF.nombre || '').trim().toLowerCase();
  let r = (PREF.rivales || ['Matilde', 'Elvira', 'Pepita']).filter(n => PERSONAJES[n] && n.toLowerCase() !== yo);
  for (const n of NOMBRES_P) { if (r.length >= PREF.jugadores - 1) break; if (!r.includes(n) && n.toLowerCase() !== yo) r.push(n); }
  return r;
}
function miAvatar() {
  if (PREF.avatar === 'google') return PREF.fotoGoogle ? 'foto:' + PREF.fotoGoogle : `letra:${((PREF.nombre || '?').trim()[0] || '?').toUpperCase()}:#4285f4`;
  if (PREF.avatar && (PREF.avatar.startsWith('letra:') || PERSONAJES[PREF.avatar])) {
    if (PREF.avatar.startsWith('letra:')) { const [, , c] = PREF.avatar.split(':'); return `letra:${((PREF.nombre || '?').trim()[0] || '?').toUpperCase()}:${c}`; }
    return PREF.avatar;
  }
  return PERSONAJES[(PREF.nombre || '').trim()] ? PREF.nombre.trim() : `letra:${((PREF.nombre || '?').trim()[0] || '?').toUpperCase()}:#e07a3a`;
}
const avatarSVGmini = k => `<span class="avatar peq">${avatarSVG(k)}</span>`;
const conInicial = (n, f) => { fotoInicial = (n || '?').trim()[0] || '?'; try { return f(); } finally { fotoInicial = null; } };
const ava = (p, cls = '') => `<span class="avatar ${cls}">${conInicial(p.nombre, () => avatarSVG(p.avatar ?? G.jugadores.indexOf(p)))}</span>`;

